#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.
#
# shellcheck disable=SC1087,SC2317
#   SC1087: the library's "$e[Enter keeps current]" suffix is literal text after a
#     variable expansion, not an array subscript — a false positive, and the
#     library is shared verbatim across wizards so it is not rewritten here.
#   SC2317: the library carries helpers (set_secret/set_var, for gh) that this
#     particular wizard never calls; they are reachable for other wizards.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=8

REPO_DIR="${REPO_DIR:-$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)}"
ENV_FILE="$REPO_DIR/.env"
TS_HOST="${TS_HOST:-$(hostname -s)}"
TS_DNS="${TS_DNS:-}"          # <name>.<tailnet>.ts.net, no trailing dot
REDIRECT_URI="${REDIRECT_URI:-}"  # https://$TS_DNS/p/api/connectors/callback

say_dns() { [[ -n "$TS_DNS" ]] && note "tailnet host: https://$TS_DNS"; }

banner "Google connectors over Tailscale Funnel"

# ── Stage 1: preflight ────────────────────────────────────────────────────
stage "Preflight: what this will change"
say "This sets up the OAuth callback for Gmail/Calendar connectors (#367/#371)."
say "Plan: Tailscale Funnel terminates public TLS on 443 and forwards to the"
say "      existing nginx proxy on localhost:8080. No ports are opened, no"
say "      domain is bought. The app keeps its current Server URL; only the"
say "      OAuth callback travels over the funnel."
printf '\n'
say "What is on disk right now:"
for k in GOOGLE_CLIENT_ID GOOGLE_CLIENT_SECRET GOOGLE_REDIRECT_URL CONNECTORS_ENCRYPTION_KEY; do
  if v=$(_existing "$k" 2>/dev/null) && [[ -n "$v" ]]; then note "  $k: set"
  else note "  $k: MISSING"; fi
done
say "  tailscale: $(command -v tailscale >/dev/null 2>&1 && echo installed || echo 'not installed')"
say "  proxy :8080: $(ss -lnt 2>/dev/null | grep -q ':8080 ' && echo listening || echo 'NOT listening')"
printf '\n'
note "This host is the live stack. Writing .env is safe (inert until the"
note "connectors image is deployed). Nothing is restarted by this wizard."
printf '\n'
if ! confirm "Proceed with Tailscale Funnel setup on this host?"; then
  say "Stopped. Nothing changed."
  exit 1
fi

# ── Stage 2: install ──────────────────────────────────────────────────────
stage "Install Tailscale"
if command -v tailscale >/dev/null 2>&1; then
  note "already installed: $(tailscale version 2>/dev/null | head -n1 || true)"
else
  say "Installing from Tailscale's official apt repo (Ubuntu $(sed -n 's/^VERSION_CODENAME=//p' /etc/os-release))."
  note "This adds /etc/apt/sources.list.d/tailscale.list and the tailscaled service."
  printf '\n'
  if ! confirm "Install Tailscale now?"; then
    warn "skipped install; re-run this wizard when ready"
    exit 1
  fi
  curl -fsSL https://tailscale.com/install.sh | sh
  printf '\n'
  printf '  %s✓%s installed %s\n' "$GREEN" "$RESET" "$(tailscale version 2>/dev/null | head -n1 || true)"
fi
say "Service: $(systemctl is-active tailscaled 2>/dev/null || true)"

# ── Stage 3: join the tailnet ─────────────────────────────────────────────
stage "Join your tailnet"
if tailscale status --json 2>/dev/null | jq -e '.BackendState == "Running"' >/dev/null 2>&1; then
  note "already connected"
  TS_HOST=$(tailscale status --json | jq -r '.Self.HostName')
else
  say "The machine name becomes the public hostname: <name>.<tailnet>.ts.net"
  step "Pick a short lowercase name (letters, digits, hyphen)."
  ask TS_HOST "Machine name [$TS_HOST]:"
  TS_HOST="${TS_HOST:-$(hostname -s)}"
  printf '\n'
  say "Opening a login URL. Sign in with your Tailscale account (creating one"
  say "on the free Personal plan is fine) and approve this machine."
  printf '\n'

  LOG=$(mktemp)
  tailscale up --hostname="$TS_HOST" >"$LOG" 2>&1 &
  TS_PID=$!
  URL=""
  for _ in $(seq 1 60); do
    URL=$(grep -oE 'https://login\.tailscale\.com/[^[:space:]]+' "$LOG" | head -n1 || true)
    [[ -n "$URL" ]] && break
    kill -0 "$TS_PID" 2>/dev/null || break
    sleep 1
  done
  if [[ -n "$URL" ]]; then
    open_url "$URL"
    pause "Press Enter once you've approved the machine in the browser."
  else
    warn "no login URL appeared; output so far:"
    sed 's/^/      /' "$LOG" || true
    pause "Fix the above, then press Enter to check again."
  fi
  for _ in $(seq 1 60); do
    tailscale status --json 2>/dev/null | jq -e '.BackendState == "Running"' >/dev/null 2>&1 && break
    sleep 2
  done
  rm -f "$LOG"
fi

if ! tailscale status --json 2>/dev/null | jq -e '.BackendState == "Running"' >/dev/null 2>&1; then
  warn "tailscaled is not Running yet. Re-run the wizard when it is."
  tailscale status || true
  exit 1
fi

TS_DNS=$(tailscale status --json 2>/dev/null | jq -r '.Self.DNSName // empty' | sed 's/\.$//' || true)
if [[ -z "$TS_DNS" || "$TS_DNS" == "null" ]]; then
  warn "could not read the tailnet DNS name (is MagicDNS enabled?)"
  exit 1
fi
printf '\n'
printf '  %s✓%s %s\n' "$GREEN" "$RESET" "https://$TS_DNS"

# ── Stage 4: funnel + public verification ─────────────────────────────────
stage "Publish the callback over HTTPS"
say "Funnel will terminate TLS with a publicly-trusted certificate and forward"
say "to the existing proxy on localhost:8080. Only ports 443/8443/10000 are"
say "allowed, so 443 it is."
printf '\n'
note "First run may prompt you to enable HTTPS certificates / MagicDNS for the"
note "tailnet. If it complains, enable them and re-run this stage:"
note "  https://console.tailscale.com/admin/dns"
printf '\n'

FOUT=$(mktemp)
if ! tailscale funnel --bg --https=443 http://127.0.0.1:8080 >"$FOUT" 2>&1; then
  warn "funnel did not start:"
  sed 's/^/      /' "$FOUT" || true
  pause "Fix the above (usually MagicDNS/HTTPS in the admin console), then press Enter to retry."
  tailscale funnel --bg --https=443 http://127.0.0.1:8080 >"$FOUT" 2>&1 || {
    warn "still failing:"; sed 's/^/      /' "$FOUT" || true; exit 1; }
fi
sed 's/^/      /' "$FOUT" || true
rm -f "$FOUT"
printf '\n'

REDIRECT_URI="https://$TS_DNS/p/api/connectors/callback"
say "Waiting for public DNS + certificate (can take a few minutes)…"
ok=0
for _ in $(seq 1 30); do
  if curl -fsS --max-time 10 "https://$TS_DNS/p/healthz" >/dev/null 2>&1; then ok=1; break; fi
  printf '%s' '.'; sleep 10
done
printf '\n'
if (( ok )); then
  printf '  %s✓%s public HTTPS reachable: https://%s/p/healthz\n' "$GREEN" "$RESET" "$TS_DNS"
  issuer=$(openssl s_client -connect "$TS_DNS:443" -servername "$TS_DNS" </dev/null 2>/dev/null \
           | openssl x509 -noout -issuer 2>/dev/null || true)
  [[ -n "$issuer" ]] && note "$issuer" && note "Google accepts Let's Encrypt-issued certs."
else
  warn "not reachable yet (DNS can take up to 10 min to propagate)."
  warn "Re-run the wizard later; the .env write below still holds."
fi
printf '\n'
say "This is the exact string to register in Google (copy it verbatim):"
printf '\n  %s%s%s\n\n' "$BOLD" "$REDIRECT_URI" "$RESET"
note "Through the proxy, /p/ is stripped before pi sees it, so this lands on"
note "/api/connectors/callback — the one route that needs no bearer."
note "Do NOT register the bare https://$TS_DNS/api/... form: on this proxy that"
note "path goes to health-api, not to pi-gateway."
pause "Press Enter once you've copied it."

# ── Stage 5: GCP project + APIs ───────────────────────────────────────────
stage "Google Cloud: project + APIs"
if ! confirm "Have a Google Cloud project with the Gmail and Calendar APIs enabled?"; then
  step "Create a project (any name, e.g. agento-connectors)."
  open_url "https://console.cloud.google.com/projectcreate"
  pause "Press Enter once the project exists and is selected in the top bar."
  step "Enable the Gmail API."
  open_url "https://console.cloud.google.com/apis/library/gmail.googleapis.com"
  pause "Press Enter once it says 'API enabled'."
  step "Enable the Google Calendar API."
  open_url "https://console.cloud.google.com/apis/library/calendar-json.googleapis.com"
  pause "Press Enter once it says 'API enabled'."
else
  note "skipped (already enabled)"
fi

# ── Stage 6: consent screen ───────────────────────────────────────────────
stage "Google Cloud: consent screen + scopes"
say "User type EXTERNAL, publishing status TESTING, yourself as a test user."
note "Testing is the only free option here: publishing needs Google"
note "verification (a paid CASA assessment) for these restricted scopes."
note "Cost of Testing: refresh tokens expire after 7 days, so Gmail/Calendar"
note "will ask you to reconnect about weekly. Expected, not a bug."
printf '\n'
open_url "https://console.cloud.google.com/auth/overview"
note "If that 404s, use APIs & Services → OAuth consent screen."
printf '\n'
step "Branding: app name, your support email, developer contact. Save."
step "Audience: External. (If it defaults to Internal, you need Workspace — pick External.)"
step "Data access → Add or remove scopes. Add exactly these three:"
printf '\n'
printf '      %s\n' "https://www.googleapis.com/auth/gmail.readonly"
printf '      %s\n' "https://www.googleapis.com/auth/gmail.compose"
printf '      %s\n' "https://www.googleapis.com/auth/calendar.readonly"
printf '\n'
note "Leave 'Google APIs' filter on 'Manually add' if the picker won't find them."
step "Audience → Test users → Add users → your own Gmail address."
printf '\n'
if ! confirm "Consent screen configured with those three scopes and yourself as a test user?"; then
  warn "re-run the wizard when it is; nothing below needs redoing"
  exit 1
fi

# ── Stage 7: OAuth client ─────────────────────────────────────────────────
stage "Google Cloud: OAuth client"
say "Create a Web application client whose redirect URI is exactly:"
printf '\n  %s%s%s\n\n' "$BOLD" "$REDIRECT_URI" "$RESET"
open_url "https://console.cloud.google.com/auth/clients"
note "Or: APIs & Services → Credentials → Create credentials → OAuth client ID."
printf '\n'
step "Application type: Web application."
step "Authorized redirect URIs → Add URI → paste the string above, then Create."
note "One URI only. A typo here surfaces later as redirect_uri_mismatch in the"
note "browser while every server-side check still passes."
printf '\n'
pause "Press Enter once the client is created and the dialog shows ID + secret."
step "Copy the Client ID (…apps.googleusercontent.com)."
ask GOOGLE_CLIENT_ID "Client ID:"
step "Copy the Client secret (starts GOCSPX-). It is shown once."
ask_secret GOOGLE_CLIENT_SECRET "Client secret (hidden):"

printf '\n'
say "Checking the two values look like what Google issues…"
if [[ "$GOOGLE_CLIENT_ID" != *".apps.googleusercontent.com" ]]; then
  warn "client id doesn't end in .apps.googleusercontent.com — double-check it"
  if ! confirm "Keep it anyway?"; then exit 1; fi
fi
if [[ "$GOOGLE_CLIENT_SECRET" != GOCSPX-* ]]; then
  warn "client secret doesn't start with GOCSPX- — double-check it"
  if ! confirm "Keep it anyway?"; then exit 1; fi
fi

# ── Stage 8: write .env + verify ──────────────────────────────────────────
stage "Write .env and verify"
[[ -f "$ENV_FILE" ]] || { warn "no $ENV_FILE at $REPO_DIR"; exit 1; }
BACKUP="$ENV_FILE.bak.$(date +%Y%m%d%H%M%S)"
cp -p "$ENV_FILE" "$BACKUP"
note "backup: $BACKUP"

if v=$(_existing CONNECTORS_ENCRYPTION_KEY 2>/dev/null) && [[ -n "$v" ]]; then
  note "keeping the existing envelope key (rotating it would invalidate every stored grant)"
  CONNECTORS_ENCRYPTION_KEY="$v"
else
  CONNECTORS_ENCRYPTION_KEY=$(openssl rand -hex 32)
  note "generated a new envelope key (AES-256-GCM, 32 bytes hex)"
fi

# A comment block once; write_env only replaces key lines, so this survives re-runs.
if ! grep -q '^# ── Google connectors' "$ENV_FILE"; then
  {
    printf '\n'
    printf '# ── Google connectors (#316) — added by setup wizard ──\n'
    printf '# Callback is served over Tailscale Funnel: https://%s\n' "$TS_DNS"
    printf '# all-four-or-nothing: any missing piece leaves OAuth unconfigured (connect → 501).\n'
  } >> "$ENV_FILE"
fi

write_env GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID"
write_env GOOGLE_CLIENT_SECRET "$GOOGLE_CLIENT_SECRET"
write_env GOOGLE_REDIRECT_URL "$REDIRECT_URI"
write_env CONNECTORS_ENCRYPTION_KEY "$CONNECTORS_ENCRYPTION_KEY"

printf '\n'
say "Rendering compose to prove all four interpolate (values not printed)…"
if ( cd "$REPO_DIR" && podman-compose --env-file "$ENV_FILE" -f docker/docker-compose.yml config ) >/tmp/oc-compose-out 2>/tmp/oc-compose-err; then
  for k in GOOGLE_CLIENT_ID GOOGLE_CLIENT_SECRET GOOGLE_REDIRECT_URL CONNECTORS_ENCRYPTION_KEY; do
    if grep -qE "^[[:space:]]*(-[[:space:]]*)?${k}[:=][[:space:]]*[^[:space:]]" /tmp/oc-compose-out; then
      printf '  %s✓%s %s reaches the pi service\n' "$GREEN" "$RESET" "$k"
    else
      printf '  %s✗%s %s is MISSING from the rendered config\n' "$YELLOW" "$RESET" "$k"
    fi
  done
else
  warn "compose render failed:"
  sed 's/^/      /' /tmp/oc-compose-err || true
fi
rm -f /tmp/oc-compose-out /tmp/oc-compose-err

finish

# ── Closing checklist (not a stage; nothing else is automated) ────────────
printf '%s  Next, in this order:%s\n' "$BOLD" "$RESET"
printf '  1. Nothing is restarted yet. These vars are inert until the connectors\n'
printf '     image is deployed — the running image predates #367/#371.\n'
printf '  2. Merge #371, rebuild the pi image, bring the stack up.\n'
printf '  3. Compare the canonical string the gateway logs at boot:\n'
printf '       podman logs docker_pi_1 | grep "OAuth configured"\n'
printf '     with what is registered in Google. They must match byte-for-byte;\n'
printf '     the log prints the canonical form, so register THAT.\n'
printf '  4. In the app: Settings → Connectors → Connect Gmail. Expect the\n'
printf '     "app isn'"'"'t verified" warning (Testing mode) → Advanced → proceed.\n'
printf '\n'
printf '  Re-running this wizard is safe: it keeps existing values as defaults.\n'
printf '  Envelope key: BACKUP FIRST — rotating it invalidates every stored grant.\n\n'
}

run_wizard "$@"; exit
